} else {
$graph_opts = $graph_data_array['output_filename'] . RRD_NL;
}
}


if (isset($graph_data_array['export_realtime']) || (isset($graph_data_array['image_format']) && $graph_data_array['image_format'] == 'png')) {
$graph['image_format_id'] = 1;
}


$graph_opts .=
