break;
case "graph_nolegend":
if (isset($graph_data_array["graph_nolegend"])) {
$graph_opts .= "--no-legend" . RRD_NL;
} else {
$graph_opts .= "";
}
break;
case "base_value":
if ($value == 1000 || $value == 1024) {
