$_cf = $rra->getElementsByTagName('cf')->item(0)->nodeValue;
$_pdp_per_row = $rra->getElementsByTagName('pdp_per_row')->item(0)->nodeValue;
$_xff = $rra->getElementsByTagName('xff')->item(0)->nodeValue;
