$graph_opts .= "--units-length " . cacti_escapeshellarg($value) . RRD_NL;
}
break;
case "tab_width":
if (!empty($value)) {
$graph_opts .= "--tabwidth " . cacti_escapeshellarg($value) . RRD_NL;
}
break;
case "dynamic_labels":
if ($value == CHECKED) {
$graph_opts .= "--dynamic-labels" . RRD_NL;
