break;
case GRAPH_ITEM_TYPE_TEXTALIGN:
if (!isset($graph_data_array['graph_nolegend'])) {
if (!empty($graph_item['textalign'])) {
$txt_graph_items .= $graph_item_types[$graph_item['graph_type_id']] . ':' . $graph_item['textalign'];
