break;
case GRAPH_ITEM_TYPE_GPRINT:
$graph_variables['text_format'][$graph_item_id] = rrdtool_escape_string(htmlspecialchars($graph_variables['text_format'][$graph_item_id], ENT_QUOTES, 'UTF-8'));

if ($graph_item['vdef_id'] == '0') {
