break;
case GRAPH_ITEM_TYPE_VRULE:
if (substr_count($graph_item['value'], ':')) {
$value_array = explode(':', $graph_item['value']);

if ($value_array[0] < 0) {
$value = date('U') - (-3600 * $value_array[0]) - 60 * $value_array[1];
} else {
